const lv_image_dsc_t *launcher_app_image(const char *key)
{
    if (!key) return NULL;
    if (!strcmp(key, "audio")) return &audio_img;
    if (!strcmp(key, "clock")) return &clock_img;
    if (!strcmp(key, "dice")) return &dice_img;
    if (!strcmp(key, "dollar")) return &dollar_img;
    if (!strcmp(key, "fire")) return &fire_img;
    if (!strcmp(key, "flashlight")) return &flashlight_img;
    if (!strcmp(key, "heart")) return &heart_img;
    if (!strcmp(key, "keyboard")) return &keyboard_img;
    if (!strcmp(key, "level")) return &level_img;
    if (!strcmp(key, "list")) return &list_img;
    if (!strcmp(key, "metronome")) return &metronome_img;
    if (!strcmp(key, "microphone")) return &microphone_img;
    if (!strcmp(key, "plus")) return &plus_img;
    if (!strcmp(key, "settings")) return &settings_img;
    if (!strcmp(key, "simon")) return &simon_img;
    if (!strcmp(key, "stopwatch")) return &stopwatch_img;
    if (!strcmp(key, "sun")) return &sun_img;
    if (!strcmp(key, "thermometer")) return &thermometer_img;
    if (!strcmp(key, "tint")) return &tint_img;
    if (!strcmp(key, "wifi")) return &wifi_img;
    return NULL;
}
